                    </div>
                </div>

                {/* Results Panel */}
                <div className={`grid grid-cols-1 md:grid-cols-2 gap-8 transition-all duration-700 ${!results ? 'opacity-30 blur-[2px] pointer-events-none select-none' : 'opacity-100 blur-0'}`}>
