                                        {item}
                                    </li>
                                )) : [1, 2, 3].map((i) => (
                                    <li key={i} className="flex items-start">
                                        <div className="h-4 bg-gray-100 rounded w-full"></div>
                                    </li>
                                ))}
                            </ul>
                        </div>
                    </div>
                </div>

                {/* Lead Capture Section */}
                {results && (
                    <div className="mt-12 bg-white border border-gray-200 rounded-2xl p-8 shadow-xl animate-fadeIn max-w-2xl mx-auto">
                        {!leadSubmitted ? (
                            <>
                                <h3 className="text-2xl font-bold text-gray-900 mb-2 text-center">Want help fixing this?</h3>
                                <p className="text-gray-600 mb-8 font-medium text-center leading-relaxed">If you'd like us to fix these issues or set this up for you, leave your details below.</p>
                                <form onSubmit={handleLeadSubmit} className="space-y-5">
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                                        <div>
                                            <label className="block text-xs font-bold text-gray-500 uppercase tracking-wider mb-2">Full Name *</label>
                                            <input 
                                                type="text" 
                                                required 
                                                value={leadName}
                                                onChange={(e) => setLeadName(e.target.value)}
                                                placeholder="John Doe"
                                                className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-primary focus:border-primary outline-none transition-all" 
