import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import { GoogleGenAI, Modality, LiveServerMessage } from '@google/genai';
import { FAQ_DATA, PRICING_PLANS } from '../constants';

// Helper for Base64 encoding/decoding as required by SDK rules
function encode(bytes: Uint8Array) {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
}

function decode(base64: string) {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
        bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
}

async function decodeAudioData(
    data: Uint8Array,
    ctx: AudioContext,
    sampleRate: number,
    numChannels: number,
): Promise<AudioBuffer> {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
    for (let channel = 0; channel < numChannels; channel++) {
        const channelData = buffer.getChannelData(channel);
        for (let i = 0; i < frameCount; i++) {
            channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
        }
    }
    return buffer;
}

const VoiceDemoPage: React.FC = () => {
    const [isActive, setIsActive] = useState(false);
    const [status, setStatus] = useState<'Idle' | 'Listening' | 'Thinking' | 'Speaking'>('Idle');
    const [transcript, setTranscript] = useState<{ role: 'user' | 'agent', text: string }[]>([]);
    const [manualKnowledge, setManualKnowledge] = useState('');
    const [summary, setSummary] = useState<any>(null);

    const sessionRef = useRef<any>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const outputAudioContextRef = useRef<AudioContext | null>(null);
    const nextStartTimeRef = useRef(0);
    const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

    useEffect(() => {
        document.title = "AI Voice Agent Demo | Elite Agent Hub";
    }, []);

    const startSession = async () => {
        if (!process.env.API_KEY) {
            alert("API Key is missing. Please ensure it is configured.");
            return;
        }

        try {
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            setIsActive(true);
            setStatus('Listening');

            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
            outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

            const systemInstruction = `
                Agent name: Belle. You are the Elite Agent Hub voice demo.
                Tone: professional, calm, friendly, concise.

                KNOWLEDGE BASE:
                - FAQs: ${JSON.stringify(FAQ_DATA)}
                - Pricing: ${JSON.stringify(PRICING_PLANS)}
                - Additional Context: ${manualKnowledge}

                CONVERSATION RULES:
                1. Greet: "Hi! I'm Belle, the Elite Agent Hub voice demo. What can I help you with today?"
                2. If user mentions emergency: "Please call 911 or your local emergency number immediately."
                3. Refuse medical/legal advice politely.
                4. For specific prices, say: "Detailed pricing is on our Pricing page. I can guide you there or we can book a demo to find your best fit."
                5. Goal: Help the user understand missed-call recovery and guide them to "Book a Demo".
                6. If buying intent is shown, ask: Business type, City, and if they miss calls today.
            `;

            let currentInText = "";
            let currentOutText = "";

            const sessionPromise = ai.live.connect({
                model: 'gemini-2.5-flash-native-audio-preview-12-2025',
                callbacks: {
                    onopen: () => {
                        const source = audioContextRef.current!.createMediaStreamSource(stream);
                        const scriptProcessor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);
                        scriptProcessor.onaudioprocess = (e) => {
                            const inputData = e.inputBuffer.getChannelData(0);
                            const l = inputData.length;
                            const int16 = new Int16Array(l);
                            for (let i = 0; i < l; i++) {
                                int16[i] = inputData[i] * 32768;
                            }
                            const pcmBlob = {
                                data: encode(new Uint8Array(int16.buffer)),
                                mimeType: 'audio/pcm;rate=16000',
                            };
                            sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
                        };
                        source.connect(scriptProcessor);
                        scriptProcessor.connect(audioContextRef.current!.destination);
                    },
                    onmessage: async (message: LiveServerMessage) => {
                        if (message.serverContent?.inputTranscription) {
                            currentInText += message.serverContent.inputTranscription.text;
                        }
                        if (message.serverContent?.outputTranscription) {
                            currentOutText += message.serverContent.outputTranscription.text;
                        }

                        if (message.serverContent?.modelTurn?.parts[0]?.inlineData) {
                            setStatus('Speaking');
                            const base64Audio = message.serverContent.modelTurn.parts[0].inlineData.data;
                            const ctx = outputAudioContextRef.current!;
                            nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
                            const audioBuffer = await decodeAudioData(decode(base64Audio), ctx, 24000, 1);
                            const source = ctx.createBufferSource();
                            source.buffer = audioBuffer;
                            source.connect(ctx.destination);
                            source.start(nextStartTimeRef.current);
                            nextStartTimeRef.current += audioBuffer.duration;
                            sourcesRef.current.add(source);
                            source.onended = () => {
                                sourcesRef.current.delete(source);
                                if (sourcesRef.current.size === 0) setStatus('Listening');
                            };
                        }

                        if (message.serverContent?.turnComplete) {
                            if (currentInText) setTranscript(prev => [...prev, { role: 'user', text: currentInText }]);
                            if (currentOutText) setTranscript(prev => [...prev, { role: 'agent', text: currentOutText }]);
                            currentInText = "";
                            currentOutText = "";
                        }

                        if (message.serverContent?.interrupted) {
                            sourcesRef.current.forEach(s => s.stop());
                            sourcesRef.current.clear();
                            nextStartTimeRef.current = 0;
                            setStatus('Listening');
                        }
                    },
                    onclose: () => stopSession(),
                    onerror: () => stopSession(),
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
                    systemInstruction: systemInstruction,
                    inputAudioTranscription: {},
                    outputAudioTranscription: {}
                }
            });

            sessionRef.current = await sessionPromise;
        } catch (err) {
            console.error(err);
            setIsActive(false);
        }
    };

    const stopSession = () => {
        setIsActive(false);
        setStatus('Idle');
        if (sessionRef.current) {
            // No direct session.close() provided in some SDK versions, assuming cleanup
            sessionRef.current = null;
        }
        if (audioContextRef.current) audioContextRef.current.close();
        if (outputAudioContextRef.current) outputAudioContextRef.current.close();

        // Generate Mock Summary
        if (transcript.length > 0) {
            setSummary({
                intent: "General Inquiry",
                questions: transcript.filter(t => t.role === 'user').length,
                recommendation: "Book a Demo to explore scaling options."
            });
        }
    };

    return (
        <div className="bg-white py-12 md:py-20 min-h-screen">
            <div className="container mx-auto px-4 max-w-5xl">
                <div className="text-center mb-12">
                    <h1 className="text-4xl md:text-5xl font-extrabold text-gray-900">Elite Voice Agent Demo</h1>
                    <p className="mt-4 text-lg text-gray-700 font-medium">Talk to Belle, our AI receptionist. Ask about pricing, setup, or missed-call recovery.</p>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
                    {/* Control Panel */}
                    <div className="lg:col-span-2 flex flex-col gap-6">
                        <div className="bg-slate-900 rounded-3xl p-10 flex flex-col items-center justify-center min-h-[400px] shadow-2xl relative overflow-hidden">
                            {/* Pulse Animation */}
                            <div className={`absolute w-64 h-64 rounded-full border-4 border-primary/30 transition-all duration-1000 ${isActive ? 'animate-ping scale-150' : 'opacity-0'}`}></div>
                            <div className={`absolute w-48 h-48 rounded-full border-2 border-primary/50 transition-all duration-700 ${isActive ? 'animate-pulse' : 'opacity-0'}`}></div>

                            <div className="relative z-10 flex flex-col items-center">
                                <div className={`w-32 h-32 rounded-full flex items-center justify-center shadow-lg transition-all ${isActive ? 'bg-primary' : 'bg-gray-700'}`}>
                                    <svg xmlns="http://www.w3.org/2000/svg" className={`h-16 w-16 text-white ${isActive ? 'animate-bounce' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
                                    </svg>
                                </div>
                                <div className="mt-8 text-center">
                                    <p className="text-white text-xl font-bold uppercase tracking-widest">{status}</p>
                                    <p className="text-gray-400 text-sm mt-2">{isActive ? "Belle is listening..." : "Click start to begin the conversation"}</p>
                                </div>

                                <div className="mt-10 flex gap-4">
                                    {!isActive ? (
                                        <button onClick={startSession} className="bg-primary hover:bg-primary-dark text-white px-8 py-4 rounded-xl font-black text-lg shadow-xl transition-transform hover:scale-105 active:scale-95">
                                            Start Demo
                                        </button>
                                    ) : (
                                        <button onClick={stopSession} className="bg-red-600 hover:bg-red-700 text-white px-8 py-4 rounded-xl font-black text-lg shadow-xl transition-transform hover:scale-105 active:scale-95">
                                            End Session
                                        </button>
                                    )}
                                </div>
                            </div>
                        </div>

                        {/* Transcript panel */}
                        <div className="bg-gray-50 border border-gray-200 rounded-2xl p-6 h-[300px] overflow-y-auto shadow-inner flex flex-col gap-4">
                            <h3 className="text-sm font-bold text-gray-400 uppercase tracking-widest sticky top-0 bg-gray-50 pb-2">Live Transcript</h3>
                            {transcript.length === 0 && <p className="text-gray-400 italic text-center mt-10">No conversation history yet.</p>}
                            {transcript.map((msg, idx) => (
                                <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                                    <div className={`max-w-[80%] rounded-2xl px-4 py-3 text-sm font-medium ${msg.role === 'user' ? 'bg-primary text-white rounded-br-none' : 'bg-white border border-gray-200 text-gray-800 rounded-bl-none shadow-sm'}`}>
                                        <span className="block text-[10px] uppercase opacity-50 mb-1">{msg.role}</span>
                                        {msg.text}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Sidebar / KB / Summary */}
                    <div className="flex flex-col gap-6">
                        <div className="bg-white border border-gray-200 rounded-2xl p-6 shadow-sm">
                            <h3 className="text-lg font-bold text-gray-900 mb-4">Try Asking:</h3>
                            <ul className="space-y-3">
                                {["How does setup work?", "Tell me about pricing", "How do you recover missed calls?", "I need a website build"].map((q, i) => (
                                    <li key={i} className="text-sm text-gray-600 font-medium bg-gray-50 px-4 py-2 rounded-lg border border-gray-100 italic">"{q}"</li>
                                ))}
                            </ul>
                        </div>

                        <div className="bg-blue-50 border border-blue-100 rounded-2xl p-6 shadow-sm">
                            <h3 className="text-lg font-bold text-blue-900 mb-2">Knowledge Injection</h3>
                            <p className="text-xs text-blue-700 mb-4 leading-relaxed italic">Paste business-specific notes here before starting to train the agent for this session.</p>
                            <textarea 
                                value={manualKnowledge}
                                onChange={(e) => setManualKnowledge(e.target.value)}
                                placeholder="e.g. We are closed on Mondays. Our owner is John Doe..."
                                className="w-full h-32 text-sm p-3 rounded-xl border border-blue-200 focus:ring-2 focus:ring-primary outline-none"
                            />
                        </div>

                        {summary && (
                            <div className="bg-green-50 border border-green-200 rounded-2xl p-6 shadow-sm animate-fadeIn">
                                <h3 className="text-lg font-bold text-green-900 mb-2">Session Summary</h3>
                                <div className="space-y-2 text-sm text-green-800">
                                    <p><strong>Intent:</strong> {summary.intent}</p>
                                    <p><strong>Exchanges:</strong> {summary.questions}</p>
                                    <p><strong>Recommended:</strong> {summary.recommendation}</p>
                                </div>
                                <Link to="/book-demo" className="mt-4 block w-full text-center bg-green-600 hover:bg-green-700 text-white font-bold py-2 rounded-lg shadow-md transition-colors">
                                    Book Real Demo
                                </Link>
                            </div>
                        )}
                    </div>
                </div>

                <div className="mt-16 text-center text-gray-500 text-xs max-w-2xl mx-auto space-y-4">
                    <p>Belle is a digital simulation. For production environments, Elite Agent Hub utilizes GoHighLevel telephony integrations for enterprise-grade voice and CRM routing.</p>
                    <p>Compliance: No medical, legal, or emergency advice provided. In case of emergency, call 911 immediately.</p>
                </div>
            </div>
        </div>
    );
};

