import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';

interface VoiceAgentDemoProps {
    onClose?: () => void;
}

const VoiceAgentDemo: React.FC<VoiceAgentDemoProps> = ({ onClose }) => {
    const [isActive, setIsActive] = useState(false);
    const [status, setStatus] = useState<'Idle' | 'Listening' | 'Thinking' | 'Speaking'>('Idle');
    const [transcript, setTranscript] = useState<{ role: 'user' | 'agent', text: string }[]>([]);

    const recognitionRef = useRef<any>(null);
    const synthRef = useRef<SpeechSynthesis>(window.speechSynthesis);

    // CLEANUP: Stop everything on unmount
    useEffect(() => {
        return () => {
            stopEverything();
        };
    }, []);

    const stopEverything = () => {
        if (recognitionRef.current) {
            recognitionRef.current.stop();
        }
        if (synthRef.current) {
            synthRef.current.cancel();
        }
        setIsActive(false);
        setStatus('Idle');
    };

    // The "Brain" Stub - Simulates LLM response logic
    const getBrainResponse = async (userInput: string): Promise<string> => {
        const input = userInput.toLowerCase();

        // Safety & Compliance Guards
        if (input.includes('emergency') || input.includes('911')) {
            return "If you are experiencing an emergency, please hang up and call 9-1-1 or your local emergency services immediately.";
        }
        if (input.includes('doctor') || input.includes('medical') || input.includes('legal') || input.includes('lawyer')) {
            return "I'm sorry, I'm an AI assistant for business operations and cannot provide medical or legal advice. I recommend speaking with a qualified professional.";
        }

        // Logic routing based on EAH business goals
        if (input.includes('pricing') || input.includes('cost') || input.includes('how much')) {
            return "Our pricing plans start at 120 dollars for Starter Lite and go up to 549 for Elite Unlimited. You can find the full comparison on our Pricing page, or I can help you book a demo to find your best fit.";
        }
        if (input.includes('setup') || input.includes('how long')) {
            return "Most setups are completed within 3 to 5 business days. We handle the number porting and configuration for you.";
        }
        if (input.includes('missed call') || input.includes('recovery')) {
            return "Elite Agent Hub protects your revenue by answering every call you miss. We can book appointments directly into your calendar and sync the data to your CRM.";
        }

        // Default greeting / fallback
        return "That's a great question about Elite Agent Hub. I'm Belle, the AI assistant. To give you the best answer, would you like to book a quick discovery call with our team?";
    };

    const speak = (text: string) => {
        if (!synthRef.current) return;
        synthRef.current.cancel(); // Stop current speech

        const utterance = new SpeechSynthesisUtterance(text);
        utterance.onstart = () => setStatus('Speaking');
        utterance.onend = () => {
            setStatus('Listening');
            startListening(); // Resume listening after speaking
        };

        // Try to find a nice female voice
        const voices = synthRef.current.getVoices();
        const preferredVoice = voices.find(v => v.name.includes('Google') && v.name.includes('Female')) || voices[0];
        if (preferredVoice) utterance.voice = preferredVoice;

        synthRef.current.speak(utterance);
    };

    const startListening = () => {
        const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
        if (!SpeechRecognition) {
            alert("Speech recognition is not supported in this browser. Please use Chrome.");
            return;
        }

        if (!recognitionRef.current) {
            recognitionRef.current = new SpeechRecognition();
            recognitionRef.current.continuous = false;
            recognitionRef.current.interimResults = false;
            recognitionRef.current.lang = 'en-US';

            recognitionRef.current.onresult = async (event: any) => {
                const speechToText = event.results[0][0].transcript;
                setTranscript(prev => [...prev, { role: 'user', text: speechToText }]);
                setStatus('Thinking');

                // Process through Brain
                const response = await getBrainResponse(speechToText);
                setTranscript(prev => [...prev, { role: 'agent', text: response }]);
                speak(response);
            };

            recognitionRef.current.onerror = (event: any) => {
                console.error("Speech Recognition Error", event.error);
                if (event.error !== 'no-speech') stopEverything();
            };
        }

        try {
            recognitionRef.current.start();
            setStatus('Listening');
        } catch (e) {
            // Already started
        }
    };

    const toggleAgent = () => {
        if (isActive) {
            stopEverything();
        } else {
            setIsActive(true);
            speak("Hi! I'm Belle, the Elite Agent Hub voice demo. How can I help you protect your business revenue today?");
            setTranscript([{ role: 'agent', text: "Hi! I'm Belle, the Elite Agent Hub voice demo. How can I help you protect your business revenue today?" }]);
        }
    };

    return (
        <div className="flex flex-col gap-6 w-full max-w-2xl mx-auto">
            <div className="bg-slate-900 rounded-3xl p-10 flex flex-col items-center justify-center min-h-[350px] shadow-2xl relative overflow-hidden">
                {/* Pulse Animation */}
                <div className={`absolute w-64 h-64 rounded-full border-4 border-primary/30 transition-all duration-1000 ${isActive ? 'animate-ping scale-150' : 'opacity-0'}`}></div>

                <div className="relative z-10 flex flex-col items-center">
                    <div className={`w-28 h-28 rounded-full flex items-center justify-center shadow-lg transition-all ${isActive ? 'bg-primary' : 'bg-gray-700'}`}>
                        <svg xmlns="http://www.w3.org/2000/svg" className={`h-14 w-14 text-white ${status === 'Speaking' ? 'animate-bounce' : ''} ${status === 'Listening' ? 'animate-pulse' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
                        </svg>
                    </div>

                    <div className="mt-8 text-center">
                        <p className="text-white text-xl font-bold uppercase tracking-widest">{status}</p>
                        <p className="text-gray-400 text-sm mt-2">
                            {status === 'Idle' && "Ready to talk to Belle?"}
                            {status === 'Listening' && "Belle is listening to you..."}
                            {status === 'Thinking' && "Belle is thinking..."}
                            {status === 'Speaking' && "Belle is responding..."}
                        </p>
                    </div>

                    <div className="mt-8 flex gap-4">
                        <button 
                            onClick={toggleAgent} 
                            className={`px-8 py-3 rounded-xl font-black text-lg shadow-xl transition-all transform hover:scale-105 active:scale-95 ${isActive ? 'bg-red-600 text-white' : 'bg-primary text-white'}`}
                        >
                            {isActive ? "Stop Session" : "Start Speaking"}
                        </button>
                    </div>
                </div>
            </div>

            <div className="bg-gray-50 border border-gray-200 rounded-2xl p-6 h-[250px] overflow-y-auto shadow-inner flex flex-col gap-3">
                <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest sticky top-0 bg-gray-50 pb-2">Conversation History</h3>
                {transcript.length === 0 && <p className="text-gray-400 italic text-center mt-10">Transcript will appear here...</p>}
                {transcript.map((msg, idx) => (
                    <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                        <div className={`max-w-[85%] rounded-2xl px-4 py-2 text-sm font-medium ${msg.role === 'user' ? 'bg-primary text-white rounded-br-none' : 'bg-white border border-gray-200 text-gray-800 rounded-bl-none shadow-sm'}`}>
                            <span className="block text-[9px] uppercase opacity-50 mb-0.5">{msg.role === 'agent' ? 'Belle' : 'You'}</span>
                            {msg.text}
                        </div>
                    </div>
                ))}
            </div>

            <div className="flex flex-col sm:flex-row gap-3 w-full">
                <Link to="/book-demo" onClick={onClose} className="flex-1 bg-gray-900 text-white text-center font-bold py-3 rounded-xl hover:bg-black transition-colors">
                    Book Discovery Call
                </Link>
                <Link to="/pricing" onClick={onClose} className="flex-1 bg-white border border-gray-300 text-gray-900 text-center font-bold py-3 rounded-xl hover:bg-gray-50 transition-colors">
                    View Pricing
                </Link>
            </div>
        </div>
    );
};

