            setIsActive(true);
            const welcome = "Hi! I'm Belle. Click Start Talking then speak naturally. How can I help you today?";
            setTranscript([{ role: 'agent', text: welcome }]);
            speak(welcome);
        }
    };

    return (
        <div className="flex flex-col h-full bg-white">
            {/* Instruction Line */}
            <div className="bg-blue-50 px-4 py-2 text-[11px] text-blue-700 font-bold border-b border-blue-100">
