import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';

interface VoiceAgentDemoProps {
    onClose?: () => void;
}

const VoiceAgentDemo: React.FC<VoiceAgentDemoProps> = ({ onClose }) => {
    const [isActive, setIsActive] = useState(false);
    const [status, setStatus] = useState<'Idle' | 'Listening' | 'Thinking' | 'Speaking'>('Idle');
    const [transcript, setTranscript] = useState<{ role: 'user' | 'agent', text: string }[]>([]);
    const [voices, setVoices] = useState<SpeechSynthesisVoice[]>([]);
    const [selectedVoiceURI, setSelectedVoiceURI] = useState<string>('');
    const [error, setError] = useState<string | null>(null);

    const recognitionRef = useRef<any>(null);
    const synthRef = useRef<SpeechSynthesis>(window.speechSynthesis);
    const transcriptEndRef = useRef<HTMLDivElement>(null);
    const silenceTimerRef = useRef<NodeJS.Timeout | null>(null);
    const isSpeakingRef = useRef(false);
    const accumulatedTextRef = useRef("");

    // Load and filter voices
    useEffect(() => {
        const loadVoices = () => {
            const availableVoices = window.speechSynthesis.getVoices();
            const englishVoices = availableVoices.filter(v => v.lang.startsWith('en'));
            setVoices(englishVoices);

            const best = englishVoices.find(v => 
                v.name.includes('Natural') || 
                v.name.includes('Google') || 
                v.name.includes('Enhanced')
            ) || englishVoices[0];

            if (best) setSelectedVoiceURI(best.voiceURI);
        };

        loadVoices();
        window.speechSynthesis.onvoiceschanged = loadVoices;
    }, []);

    useEffect(() => {
        transcriptEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [transcript]);

    const stopEverything = () => {
        setIsActive(false);
        isSpeakingRef.current = false;
        if (recognitionRef.current) {
            recognitionRef.current.onend = null;
            recognitionRef.current.stop();
        }
        if (synthRef.current) {
            synthRef.current.cancel();
        }
        if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);
        setStatus('Idle');
    };

    const getBrainResponse = async (userInput: string): Promise<string> => {
        // TODO: WIRE TO SERVER ENDPOINT
        // if (process.env.VITE_GEMINI_ENDPOINT) { 
        //    const res = await fetch(process.env.VITE_GEMINI_ENDPOINT, { method: 'POST', body: JSON.stringify({ prompt: userInput }) });
        //    return (await res.json()).text;
        // }

        const input = userInput.toLowerCase();
        if (input.includes('emergency') || input.includes('911')) return "Please call 9-1-1 immediately for emergency assistance.";
        if (input.includes('doctor') || input.includes('medical') || input.includes('legal')) return "I cannot provide medical or legal advice. Please consult with a professional.";
        if (input.includes('pricing') || input.includes('cost')) return "Our plans start at 120 dollars for Starter Lite. Check our pricing page for a full breakdown.";
        if (input.includes('missed call')) return "We recover missed calls by answering instantly and booking directly into your calendar.";

        return "That's helpful to know. I'm Belle. Would you like to schedule a quick discovery call with our team to discuss how we can help your business?";
    };

    const speak = (text: string) => {
        if (!synthRef.current) return;

        // Stop listening while speaking to prevent feedback loop
        if (recognitionRef.current) recognitionRef.current.stop();
        isSpeakingRef.current = true;

        // TODO: PREMIUM TTS HOOK
        // if (process.env.VITE_TTS_ENDPOINT) { /* Fetch audio stream and play */ }

        const utterance = new SpeechSynthesisUtterance(text);
        utterance.rate = 1.0; 
        utterance.pitch = 1.0;

        const voice = voices.find(v => v.voiceURI === selectedVoiceURI);
        if (voice) utterance.voice = voice;

        utterance.onstart = () => setStatus('Speaking');
        utterance.onend = () => {
            isSpeakingRef.current = false;
            if (isActive) {
                setStatus('Listening');
                startListening();
            }
        };

        synthRef.current.speak(utterance);
    };

    const handleSpeechEnd = async () => {
        const finalQuery = accumulatedTextRef.current.trim();
        if (!finalQuery) {
            startListening(); // Just keep listening if nothing was said
            return;
        }

        accumulatedTextRef.current = "";
        setTranscript(prev => [...prev, { role: 'user', text: finalQuery }]);
        setStatus('Thinking');

        const response = await getBrainResponse(finalQuery);
        setTranscript(prev => [...prev, { role: 'agent', text: response }]);
        speak(response);
    };

    const startListening = () => {
        if (isSpeakingRef.current || !isActive) return;

        const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
        if (!SpeechRecognition) {
            setError("Speech recognition not supported in this browser.");
            return;
        }

        if (!recognitionRef.current) {
            recognitionRef.current = new SpeechRecognition();
            recognitionRef.current.continuous = true;
            recognitionRef.current.interimResults = true;
            recognitionRef.current.lang = 'en-US';

            recognitionRef.current.onresult = (event: any) => {
                if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);

                let interimTranscript = '';
                for (let i = event.resultIndex; i < event.results.length; ++i) {
                    if (event.results[i].isFinal) {
                        accumulatedTextRef.current += event.results[i][0].transcript + " ";
                    } else {
                        interimTranscript += event.results[i][0].transcript;
                    }
                }

                // Silence detection: If user stops talking for 1.2s, process the input
                silenceTimerRef.current = setTimeout(() => {
                    if (isActive && !isSpeakingRef.current) {
                        handleSpeechEnd();
                    }
                }, 1200);
            };

            recognitionRef.current.onerror = (event: any) => {
                console.error("SR Error:", event.error);
                if (event.error === 'not-allowed') setError("Microphone access denied.");
            };

            recognitionRef.current.onend = () => {
                // Auto-restart logic if still active and not currently speaking
                if (isActive && !isSpeakingRef.current) {
                    setTimeout(() => startListening(), 250);
                }
            };
        }

        try {
            recognitionRef.current.start();
            setStatus('Listening');
        } catch (e) {}
    };

    const toggleAgent = () => {
        if (isActive) {
            stopEverything();
        } else {
            setError(null);
            setIsActive(true);
            const welcome = "Hi! I'm Belle. I'm listening. How can I help you protect your business revenue today?";
            setTranscript([{ role: 'agent', text: welcome }]);
            speak(welcome);
        }
    };

    return (
        <div className="flex flex-col h-full bg-white">
            <div className="bg-blue-50 px-4 py-2 text-[11px] text-blue-700 font-bold border-b border-blue-100 text-center">
                Hands-free enabled. Speak naturally, I'll wait for you to finish.
            </div>

            {error && (
                <div className="bg-red-50 text-red-600 p-3 text-xs font-bold text-center border-b border-red-100">
                    {error}
                </div>
            )}

            <div className="flex-1 overflow-y-auto p-4 space-y-4 min-h-0">
                <div className="bg-slate-900 rounded-2xl p-6 flex flex-col items-center justify-center relative overflow-hidden shadow-inner">
                    <div className={`absolute w-32 h-32 rounded-full border-2 border-primary/20 transition-all duration-1000 ${status === 'Listening' ? 'animate-ping' : ''} ${status === 'Speaking' ? 'scale-110 border-primary/40' : ''}`}></div>

                    <div className={`w-16 h-16 rounded-full flex items-center justify-center shadow-lg transition-all z-10 ${isActive ? 'bg-primary' : 'bg-gray-700'}`}>
                        <svg xmlns="http://www.w3.org/2000/svg" className={`h-8 w-8 text-white ${status === 'Speaking' ? 'animate-pulse' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
                        </svg>
                    </div>

                    <div className="mt-4 text-center z-10">
                        <span className={`inline-block px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest mb-1 shadow-sm ${isActive ? 'bg-primary text-white' : 'bg-gray-600 text-gray-300'}`}>
                            {status}
                        </span>
                    </div>

                    <div className="mt-4 w-full z-10">
                        <button 
                            onClick={toggleAgent} 
                            className={`w-full py-3 rounded-xl font-black text-sm shadow-xl transition-all transform active:scale-95 ${isActive ? 'bg-red-600 text-white hover:bg-red-700' : 'bg-primary text-white hover:bg-primary-dark'}`}
                        >
                            {isActive ? "End Session" : "Start Conversation"}
                        </button>
                    </div>
                </div>

                <div className="px-1">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1 block">Agent Voice</label>
                    <select 
                        value={selectedVoiceURI} 
                        onChange={(e) => setSelectedVoiceURI(e.target.value)}
                        className="w-full text-xs p-2 rounded-lg border border-gray-200 bg-gray-50 focus:ring-1 focus:ring-primary outline-none"
                    >
                        {voices.map(v => <option key={v.voiceURI} value={v.voiceURI}>{v.name}</option>)}
                    </select>
                </div>

                <div className="space-y-3">
                    <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest sticky top-0 bg-white py-1">Live Transcript</h3>
                    {transcript.map((msg, idx) => (
                        <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-fadeIn`}>
                            <div className={`max-w-[90%] rounded-xl px-3 py-2 text-xs font-medium ${msg.role === 'user' ? 'bg-primary text-white rounded-br-none' : 'bg-gray-100 text-gray-800 shadow-sm rounded-bl-none'}`}>
                                {msg.text}
                            </div>
                        </div>
                    ))}
                    <div ref={transcriptEndRef} />
                </div>
            </div>

            <div className="p-4 bg-gray-50 border-t border-gray-100 flex gap-2">
                <Link to="/book-demo" onClick={onClose} className="flex-1 bg-slate-900 text-white text-center text-xs font-bold py-2.5 rounded-lg hover:bg-black transition-colors">
                    Book Discovery Call
                </Link>
                <button onClick={onClose} className="px-4 text-xs font-bold text-gray-500 hover:text-gray-700 transition-colors">
                    Close
                </button>
            </div>
        </div>
    );
};

