import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';

interface VoiceAgentDemoProps {
    onClose?: () => void;
}

const VoiceAgentDemo: React.FC<VoiceAgentDemoProps> = ({ onClose }) => {
    const [isActive, setIsActive] = useState(false);
    const [status, setStatus] = useState<'Idle' | 'Listening' | 'Thinking' | 'Speaking'>('Idle');
    const [transcript, setTranscript] = useState<{ role: 'user' | 'agent', text: string }[]>([]);
    const [voices, setVoices] = useState<SpeechSynthesisVoice[]>([]);
    const [selectedVoiceURI, setSelectedVoiceURI] = useState<string>('');
    const [error, setError] = useState<string | null>(null);

    const recognitionRef = useRef<any>(null);
    const synthRef = useRef<SpeechSynthesis>(window.speechSynthesis);
    const transcriptEndRef = useRef<HTMLDivElement>(null);
    const silenceTimerRef = useRef<any>(null);
    const isSpeakingRef = useRef(false);
    const accumulatedTextRef = useRef("");
    const abortControllerRef = useRef<AbortController | null>(null);

    // 1. VOICE LOADING & SELECTION
    useEffect(() => {
        const loadVoices = () => {
            const availableVoices = window.speechSynthesis.getVoices();
            const englishVoices = availableVoices.filter(v => v.lang.startsWith('en'));
            setVoices(englishVoices);

            // Priority: Natural > Google > Enhanced > Standard
            const best = englishVoices.find(v => v.name.includes('Natural')) || 
                         englishVoices.find(v => v.name.includes('Google')) || 
                         englishVoices.find(v => v.name.includes('Enhanced')) || 
                         englishVoices[0];

            if (best) setSelectedVoiceURI(best.voiceURI);
        };

        loadVoices();
        window.speechSynthesis.onvoiceschanged = loadVoices;
        return () => {
            if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);
            stopEverything();
        };
    }, []);

    // 2. AUTO-SCROLL TRANSCRIPT
    useEffect(() => {
        transcriptEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }, [transcript]);

    // 3. CORE LIFECYCLE CONTROLS
    const stopEverything = () => {
        setIsActive(false);
        isSpeakingRef.current = false;
        setStatus('Idle');

        if (recognitionRef.current) {
            recognitionRef.current.onend = null;
            recognitionRef.current.onresult = null;
            try { recognitionRef.current.stop(); } catch(e) {}
        }
        if (synthRef.current) {
            synthRef.current.cancel();
        }
        if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);
        if (abortControllerRef.current) abortControllerRef.current.abort();
    };

    // 4. THE BRAIN (LLM HOOK)
    const getBrainResponse = async (userInput: string): Promise<string> => {
        // Preparation for Server-Side Gemini Integration
        // if (process.env.VITE_GEMINI_ENDPOINT) { ... }

        const input = userInput.toLowerCase();

        // Safety Guards
        if (input.includes('emergency') || input.includes('911')) return "Please hang up and call 9-1-1 immediately for emergency assistance.";
        if (input.includes('doctor') || input.includes('medical') || input.includes('lawyer')) return "I'm sorry, I'm an AI assistant for business and cannot provide medical or legal advice.";

        // Mock Responses for Demo
        if (input.includes('pricing') || input.includes('cost')) return "Our plans start at 120 dollars per month. Growth and Elite plans offer unlimited minutes. Which plan would you like to know more about?";
        if (input.includes('book') || input.includes('schedule') || input.includes('appointment')) return "I'd be happy to help you get scheduled. You can click the Book Discovery Call button at the bottom of this panel to see our live calendar.";
        if (input.includes('hello') || input.includes('hi')) return "Hello! I'm Belle. I'm here to show you how Elite Agent Hub handles your business calls. Go ahead, ask me anything about our services.";

        return "That's a great point. Elite Agent Hub is designed to ensure you never miss another customer. Would you like to hear about our missed-call recovery features?";
    };

    // 5. TURN-TAKING LOGIC (SPEAKING -> LISTENING)
    const speak = (text: string) => {
        if (!synthRef.current) return;

        isSpeakingRef.current = true;
        // Pause listening so Belle doesn't hear herself
        if (recognitionRef.current) {
            try { recognitionRef.current.stop(); } catch(e) {}
        }

        const utterance = new SpeechSynthesisUtterance(text);
        utterance.rate = 1.0; 
        utterance.pitch = 1.0;

        const voice = voices.find(v => v.voiceURI === selectedVoiceURI);
        if (voice) utterance.voice = voice;

        utterance.onstart = () => setStatus('Speaking');
        utterance.onend = () => {
            isSpeakingRef.current = false;
            if (isActive) {
                // IMPORTANT: Automatic turn back to User
                setStatus('Listening');
                startListening();
            }
        };

        synthRef.current.speak(utterance);
    };

    const handleSpeechDetected = async () => {
        const finalQuery = accumulatedTextRef.current.trim();
        if (!finalQuery) {
            startListening(); // Re-sync if empty
            return;
        }

        accumulatedTextRef.current = "";
        setTranscript(prev => [...prev, { role: 'user', text: finalQuery }]);
        setStatus('Thinking');

        const response = await getBrainResponse(finalQuery);
        setTranscript(prev => [...prev, { role: 'agent', text: response }]);
        speak(response);
    };

    const startListening = () => {
        if (isSpeakingRef.current || !isActive) return;

        const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
        if (!SpeechRecognition) {
            setError("Speech recognition is not supported in this browser. Please use Chrome.");
            return;
        }

        if (!recognitionRef.current) {
            recognitionRef.current = new SpeechRecognition();
            recognitionRef.current.continuous = true;
            recognitionRef.current.interimResults = true;
            recognitionRef.current.lang = 'en-US';

            recognitionRef.current.onresult = (event: any) => {
                if (silenceTimerRef.current) clearTimeout(silenceTimerRef.current);

                let interimTranscript = '';
                for (let i = event.resultIndex; i < event.results.length; ++i) {
                    if (event.results[i].isFinal) {
                        accumulatedTextRef.current += event.results[i][0].transcript + " ";
                    } else {
                        interimTranscript += event.results[i][0].transcript;
                    }
                }

                // Silence Detection: wait for 1.4s of silence before assuming User is done
                silenceTimerRef.current = setTimeout(() => {
                    if (isActive && !isSpeakingRef.current && accumulatedTextRef.current.trim().length > 0) {
                        handleSpeechDetected();
                    }
                }, 1400);
            };

            recognitionRef.current.onerror = (event: any) => {
                if (event.error === 'not-allowed') {
                    setError("Microphone access denied. Please check site permissions.");
                    stopEverything();
                }
                // Silently ignore 'no-speech' or 'network' to keep the loop alive
            };

            recognitionRef.current.onend = () => {
                // Persistence: Keep mic alive unless we are speaking or session is over
                if (isActive && !isSpeakingRef.current) {
                    setTimeout(() => {
                        try { recognitionRef.current.start(); } catch(e) {}
                    }, 300);
                }
            };
        }

        try {
            recognitionRef.current.start();
            setStatus('Listening');
        } catch (e) {
            // Error usually means it's already running
        }
    };

    const toggleAgent = () => {
        if (isActive) {
            stopEverything();
        } else {
            setError(null);
            setIsActive(true);
            const welcome = "Hi! I'm Belle, your virtual receptionist. I'm listening. How can I help you today?";
            setTranscript([{ role: 'agent', text: welcome }]);
            speak(welcome);
        }
    };

    return (
        <div className="flex flex-col h-full bg-white font-sans">
            {/* Context/Status Header */}
            <div className={`px-4 py-2 text-[11px] font-bold border-b transition-colors text-center ${status === 'Listening' ? 'bg-green-50 text-green-700 border-green-100' : 'bg-blue-50 text-blue-700 border-blue-100'}`}>
                {status === 'Listening' ? '● Live Listening Mode' : 'Hands-free Conversation Demo'}
            </div>

            {error && (
                <div className="bg-red-50 text-red-600 p-3 text-xs font-bold text-center border-b border-red-100 animate-pulse">
                    {error}
                </div>
            )}

            <div className="flex-1 overflow-y-auto p-4 space-y-4 min-h-0 bg-gray-50/30">
                {/* Visual Agent Interface */}
                <div className="bg-slate-900 rounded-3xl p-6 flex flex-col items-center justify-center relative overflow-hidden shadow-2xl border border-slate-800">
                    {/* Dynamic Background Rings */}
                    <div className={`absolute w-40 h-40 rounded-full border-2 border-primary/20 transition-all duration-700 ${status === 'Listening' ? 'animate-ping' : 'scale-0'}`}></div>
                    <div className={`absolute w-32 h-32 rounded-full border-4 border-primary/10 transition-all duration-1000 ${status === 'Speaking' ? 'scale-125 opacity-100' : 'opacity-0'}`}></div>

                    <div className={`w-20 h-20 rounded-full flex items-center justify-center shadow-2xl transition-all z-10 ${isActive ? 'bg-primary' : 'bg-gray-700'}`}>
                        <svg xmlns="http://www.w3.org/2000/svg" className={`h-10 w-10 text-white transition-transform ${status === 'Speaking' ? 'scale-110' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
                        </svg>
                    </div>

                    <div className="mt-6 text-center z-10">
                        <div className={`inline-flex items-center px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest mb-2 shadow-lg ${isActive ? 'bg-primary text-white' : 'bg-gray-700 text-gray-400'}`}>
                            {isActive ? (
                                <>
                                    <span className="w-2 h-2 rounded-full bg-white mr-2 animate-pulse"></span>
                                    {status}
                                </>
                            ) : 'Standby'}
                        </div>
                        <p className="text-gray-400 text-xs font-medium">
                            {isActive ? "Belle is ready for your question." : "Click below to start talking."}
                        </p>
                    </div>

                    <div className="mt-6 w-full z-10">
                        <button 
                            onClick={toggleAgent} 
                            className={`w-full py-4 rounded-2xl font-black text-sm uppercase tracking-wider shadow-2xl transition-all transform active:scale-95 ${isActive ? 'bg-red-600 text-white hover:bg-red-700' : 'bg-primary text-white hover:bg-primary-dark shadow-primary/20'}`}
                        >
                            {isActive ? "End Session" : "Start Conversation"}
                        </button>
                    </div>
                </div>

                {/* Voice Selector - Critical for "Human-like" goal */}
                <div className="px-1">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mb-1.5 block">AI Voice Quality</label>
                    <select 
                        value={selectedVoiceURI} 
                        onChange={(e) => setSelectedVoiceURI(e.target.value)}
                        className="w-full text-xs font-bold p-3 rounded-xl border border-gray-200 bg-white shadow-sm focus:ring-2 focus:ring-primary focus:border-primary outline-none appearance-none cursor-pointer"
                    >
                        {voices.map(v => <option key={v.voiceURI} value={v.voiceURI}>{v.name}</option>)}
                    </select>
                </div>

                {/* Live Feed */}
                <div className="flex-1 space-y-3 pb-4">
                    <h3 className="text-[10px] font-bold text-gray-400 uppercase tracking-widest sticky top-0 bg-white/80 backdrop-blur-sm py-2 z-20">Live Conversation Feed</h3>
                    {transcript.length === 0 && (
                        <div className="flex flex-col items-center justify-center py-10 text-gray-300">
                            <svg className="w-8 h-8 mb-2 opacity-20" fill="currentColor" viewBox="0 0 24 24"><path d="M20 2H4c-1.1 0-2 .9-2 2v18l4-4h14c1.1 0 2-.9 2-2V4c0-1.1-.9-2-2-2z"/></svg>
                            <p className="text-xs font-medium italic">Transcript will appear here...</p>
                        </div>
                    )}
                    {transcript.map((msg, idx) => (
                        <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-fadeIn`}>
                            <div className={`max-w-[85%] rounded-2xl px-4 py-3 text-sm font-medium leading-relaxed ${msg.role === 'user' ? 'bg-primary text-white rounded-br-none shadow-primary/10' : 'bg-white text-slate-800 shadow-sm border border-gray-100 rounded-bl-none'}`}>
                                <div className="text-[9px] uppercase tracking-tighter opacity-50 mb-1 font-black">
                                    {msg.role === 'user' ? 'You' : 'Belle (AI)'}
                                </div>
                                {msg.text}
                            </div>
                        </div>
                    ))}
                    <div ref={transcriptEndRef} />
                </div>
            </div>

            {/* Quick Actions Footer */}
            <div className="p-4 bg-white border-t border-gray-100 flex flex-col gap-3">
                <div className="flex gap-2">
                    <Link to="/book-demo" onClick={onClose} className="flex-1 bg-slate-900 text-white text-center text-xs font-black py-3 rounded-xl hover:bg-black transition-all shadow-lg">
                        Book Strategy Call
                    </Link>
                    <button onClick={onClose} className="px-6 text-xs font-black text-gray-500 hover:text-gray-900 transition-colors uppercase tracking-widest border border-gray-200 rounded-xl">
                        Close
                    </button>
                </div>
                <p className="text-[9px] text-gray-400 text-center font-medium leading-tight">
                    Powered by Elite Agent Hub Streaming Voice Engine. Privacy Protected.
                </p>
            </div>
        </div>
    );
};

