    const [textInput, setTextInput] = useState('');
    const [isRecognitionSupported] = useState(!!SpeechRecognition);

    const recognitionRef = useRef<any>(null);
    const isSpeakingRef = useRef(false);
    const sessionActiveRef = useRef(false);

    // 1. VOICE MANAGEMENT
    const loadVoices = () => {
        let availableVoices = window.speechSynthesis.getVoices();
        if (availableVoices.length > 0) {
            setVoices(availableVoices);

            // Try to find a saved voice, then a "Natural" en-US voice, then fallback
            const savedVoice = localStorage.getItem('eah_josh_voice_name');
            const bestDefault = availableVoices.find(v => v.name === savedVoice) ||
                               availableVoices.find(v => v.lang === 'en-US' && (v.name.includes('Google') || v.name.includes('Natural'))) ||
                               availableVoices.find(v => v.lang === 'en-US') ||
                               availableVoices[0];

            if (bestDefault && !selectedVoiceName) {
                setSelectedVoiceName(bestDefault.name);
            }
        }
    };

    useEffect(() => {
        loadVoices();
        window.speechSynthesis.onvoiceschanged = loadVoices;
        return () => stopSession();
    }, []);

    const handleVoiceChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
        setSelectedVoiceName(e.target.value);
        localStorage.setItem('eah_josh_voice_name', e.target.value);
    };

    // 2. CONVERSATION LOOP (BRAIN)
    const getBotResponse = (input: string) => {
        const transcript = input.toLowerCase();
        if (transcript.includes('price') || transcript.includes('cost')) {
            return "Our plans range from the Starter Lite at 120 dollars to the Elite Unlimited at 549 dollars. Which one sounds right for your business?";
        } else if (transcript.includes('belle') || transcript.includes('phone')) {
            return "Belle is our specialized phone agent. You can reach her at 804-223-3141 to experience our live GoHighLevel integration.";
        } else if (transcript.includes('book') || transcript.includes('appointment')) {
            return "I can definitely help with that. In the live version, I'd check your calendar now. For this demo, you can click 'Book a Demo' on our website.";
        }
        return "That's a great question. In our full production environment, I can handle complex bookings and data entry. For this demo, how can I help you explore Elite Agent Hub?";
    };

    // 3. SPEECH SYNTHESIS (TTS)
    const speakText = (text: string): Promise<void> => {
        return new Promise((resolve) => {
            if (!('speechSynthesis' in window)) return resolve();

            window.speechSynthesis.cancel();
            isSpeakingRef.current = true;
            setStatus('Speaking');

            // Pause recognition while speaking
            if (recognitionRef.current) {
                try { recognitionRef.current.stop(); } catch (e) {}
            }

            const utterance = new SpeechSynthesisUtterance(text);
            const voice = voices.find(v => v.name === selectedVoiceName);
            if (voice) utterance.voice = voice;

            // Safety timeout to ensure resolve
            const safetyTimeout = window.setTimeout(() => {
                onSpeechEnd();
                resolve();
            }, 8000);

            const onSpeechEnd = () => {
                window.clearTimeout(safetyTimeout);
                isSpeakingRef.current = false;
                if (sessionActiveRef.current) {
                    setStatus('Listening');
                    setTimeout(() => startListening(), 250);
                }
                resolve();
            };

            utterance.onend = onSpeechEnd;
            utterance.onerror = onSpeechEnd;
            window.speechSynthesis.speak(utterance);
        });
    };

