        if (!recognitionRef.current || isSpeakingRef.current || !sessionActiveRef.current) return;
        try {
            recognitionRef.current.start();
        } catch (e) {
            // Already started or busy
        }
    };

    const initRecognition = () => {
        if (!isRecognitionSupported) return;

        const recognition = new SpeechRecognition();
        recognition.continuous = false;
        recognition.interimResults = false;
        recognition.lang = 'en-US';

        recognition.onresult = (event: any) => {
            const transcript = event.results[0][0].transcript;
            const response = getBotResponse(transcript);
            speakText(response);
        };

        recognition.onend = () => {
            if (sessionActiveRef.current && !isSpeakingRef.current) {
                setTimeout(() => startListening(), 250);
            }
        };

        recognition.onerror = (event: any) => {
            console.error("STT Error:", event.error);
            if (event.error === 'not-allowed') {
                stopSession();
                alert("Microphone access was denied. Please check your browser settings.");
            }
        };

        recognitionRef.current = recognition;
    };

    const startSession = async () => {
        try {
            setStatus('Connecting');
            await navigator.mediaDevices.getUserMedia({ audio: true });

            initRecognition();
            sessionActiveRef.current = true;
            setIsConnected(true);

