    const decodeBase64 = (base64: string) => {
        const binaryString = atob(base64);
        const bytes = new Uint8Array(binaryString.length);
        for (let i = 0; i < binaryString.length; i++) {
            bytes[i] = binaryString.charCodeAt(i);
        }
        return bytes;
    };

    // Helper: Encode to Base64
    const encodeBase64 = (bytes: Uint8Array) => {
        let binary = '';
        for (let i = 0; i < bytes.byteLength; i++) {
            binary += String.fromCharCode(bytes[i]);
        }
        return btoa(binary);
    };

    // Helper: Convert PCM to AudioBuffer
    const createAudioBuffer = (data: Uint8Array, ctx: AudioContext) => {
        const dataInt16 = new Int16Array(data.buffer);
        const buffer = ctx.createBuffer(1, dataInt16.length, OUTPUT_SAMPLE_RATE);
        const channelData = buffer.getChannelData(0);
        for (let i = 0; i < dataInt16.length; i++) {
            channelData[i] = dataInt16[i] / 32768.0;
        }
        return buffer;
    };

    const stopSession = () => {
        setIsConnected(false);
        setStatus('Idle');
        if (sessionRef.current) {
            sessionRef.current.close();
            sessionRef.current = null;
        }
        activeSourcesRef.current.forEach(s => s.stop());
        activeSourcesRef.current.clear();
        if (audioContextRef.current) {
            audioContextRef.current.close();
            audioContextRef.current = null;
        }
    };

    const startSession = async () => {
        if (isMaintenanceMode) return;

        try {
            setStatus('Connecting');

            // 1. Setup Audio Contexts
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
            const micStream = await navigator.mediaDevices.getUserMedia({ audio: true });

            // 2. Initialize Gemini Live
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const sessionPromise = ai.live.connect({
                model: 'gemini-2.5-flash-native-audio-preview-12-2025',
                config: {
                    responseModalities: [Modality.AUDIO],
                    speechConfig: {
                        voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Puck' } } // Josh persona
                    },
                    systemInstruction: "You are Josh, the Elite Agent Hub voice demo. You are a professional, helpful AI receptionist. Keep responses concise and natural. You are talking via a live browser stream. If the user asks about Belle, her number is 804-223-3141."
                },
                callbacks: {
                    onopen: () => {
                        setIsConnected(true);
                        setStatus('Live');

                        // Start Mic Processing
                        const source = audioContextRef.current!.createMediaStreamSource(micStream);
                        const processor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);

                        processor.onaudioprocess = (e) => {
                            const inputData = e.inputBuffer.getChannelData(0);
                            const int16Data = new Int16Array(inputData.length);
                            for (let i = 0; i < inputData.length; i++) {
                                int16Data[i] = inputData[i] * 32768;
                            }

                            sessionPromise.then(session => {
                                session.sendRealtimeInput({
                                    media: {
                                        data: encodeBase64(new Uint8Array(int16Data.buffer)),
                                        mimeType: 'audio/pcm;rate=16000'
                                    }
                                });
                            });
                        };

                        source.connect(processor);
                        processor.connect(audioContextRef.current!.destination);
                    },
                    onmessage: async (message: LiveServerMessage) => {
                        const audioData = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
                        if (audioData && audioContextRef.current) {
                            const buffer = createAudioBuffer(decodeBase64(audioData), audioContextRef.current);
                            const source = audioContextRef.current.createBufferSource();
                            source.buffer = buffer;
                            source.connect(audioContextRef.current.destination);

                            const startTime = Math.max(nextStartTimeRef.current, audioContextRef.current.currentTime);
                            source.start(startTime);
                            nextStartTimeRef.current = startTime + buffer.duration;

                            activeSourcesRef.current.add(source);
                            source.onended = () => activeSourcesRef.current.delete(source);
                        }

                        if (message.serverContent?.interrupted) {
                            activeSourcesRef.current.forEach(s => s.stop());
                            activeSourcesRef.current.clear();
                            nextStartTimeRef.current = 0;
                        }
                    },
                    onclose: () => stopSession(),
                    onerror: (e) => {
                        console.error("Gemini Live Error:", e);
                        stopSession();
                    }
                }
            });

            sessionRef.current = await sessionPromise;

        } catch (err) {
            console.error("Session Startup Failed:", err);
            stopSession();
        }
    };

    useEffect(() => {
        return () => stopSession();
    }, []);

    if (isMaintenanceMode) {
        return (
            <div className="flex flex-col h-full min-h-[500px] w-full bg-white text-slate-900 font-sans rounded-3xl overflow-hidden shadow-sm p-8 text-center justify-center space-y-6">
                <div className="w-20 h-20 bg-amber-100 rounded-full flex items-center justify-center mx-auto">
                    <svg className="w-10 h-10 text-amber-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                    </svg>
                </div>
                <h3 className="text-2xl font-black">Browser Demo Offline</h3>
                <p className="text-slate-600 font-medium">
                    We are currently upgrading Josh to our new Streaming Voice Engine for a more natural experience.
                </p>
                <div className="p-4 bg-slate-50 rounded-xl border border-slate-200">
                    <p className="text-sm font-bold text-slate-900">Live Demo is still active via Phone:</p>
                    <p className="text-2xl font-black text-primary mt-1">(804) 223-3141</p>
                </div>
                <p className="text-xs text-slate-400 uppercase tracking-widest font-bold">Estimated Return: 24-48 Hours</p>
            </div>
        );
    }

    return (
        <div className="flex flex-col h-full min-h-[550px] w-full bg-white text-slate-900 font-sans rounded-3xl overflow-hidden shadow-sm pointer-events-auto">
            {/* Header */}
            <div className="p-5 border-b flex items-center justify-between bg-slate-50">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-primary rounded-full flex items-center justify-center shadow-inner">
                        <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
                        </svg>
                    </div>
                    <div>
                        <h3 className="text-base font-black uppercase tracking-tight">Josh (Live Streaming)</h3>
                        <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest leading-none">Powered by Gemini Native Audio</p>
                    </div>
                </div>
            </div>

            {/* Interaction Area */}
            <div className="flex-1 p-8 flex flex-col items-center justify-center text-center space-y-10 bg-gradient-to-b from-white to-slate-50">
                <div className="relative">
                    <div className={`absolute inset-0 rounded-full bg-primary/20 transition-all duration-700 ${isConnected ? 'animate-ping scale-150' : 'scale-100'}`}></div>
                    <div className={`w-40 h-40 rounded-full flex items-center justify-center z-10 relative transition-all duration-500 ${isConnected ? 'bg-primary shadow-[0_0_60px_rgba(37,99,235,0.4)]' : 'bg-slate-200'}`}>
                        {isConnected ? (
                            <div className="flex gap-2 items-end h-10">
                                {[1, 2, 3, 4, 5].map((i) => (
                                    <div key={i} className="w-2 bg-white rounded-full animate-bounce" style={{ animationDelay: `${i * 150}ms`, height: '100%' }}></div>
                                ))}
                            </div>
                        ) : (
                            <svg className="w-16 h-16 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
                            </svg>
                        )}
                    </div>
                </div>

                <div className="space-y-3">
                    <h4 className="text-3xl font-black text-slate-900 leading-tight">
                        {status === 'Connecting' ? "Establishing Stream..." : isConnected ? "Josh is Live" : "Hands-Free Demo"}
                    </h4>
                    <p className="text-base text-slate-500 font-medium max-w-xs mx-auto">
                        {isConnected 
                            ? "Speak naturally. Josh will reply instantly via streaming audio." 
                            : "Start the session to speak with our advanced native voice agent."}
                    </p>
                </div>

                <div className="w-full max-w-sm flex flex-col items-center gap-4">
                    <button
                        onClick={isConnected ? stopSession : startSession}
                        disabled={status === 'Connecting'}
                        className={`w-full py-5 rounded-2xl font-black text-base uppercase tracking-widest shadow-xl transition-all transform active:scale-95 flex items-center justify-center gap-4 ${isConnected ? 'bg-red-600 text-white hover:bg-red-700' : 'bg-primary text-white hover:bg-primary-dark'} ${status === 'Connecting' ? 'opacity-50 cursor-wait' : ''}`}
                    >
                        {status === 'Connecting' ? "Connecting..." : isConnected ? "End Session" : "Start Conversation"}
                    </button>
                    {!isConnected && (
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                            Requires Microphone Access
                        </p>
                    )}
                </div>
            </div>

            <div className="p-5 border-t text-center bg-white">
                <p className="text-[11px] text-gray-400 font-bold uppercase tracking-widest leading-relaxed">
                    Ultra-Low Latency Voice Protocol <br/> 
                    Server-Side Authentication Enabled
                </p>
            </div>
        </div>
    );
};

