I will implement the production-grade architecture using a Node.js WebSocket proxy and an AudioWorklet-based frontend. This ensures zero API keys in the browser, high-performance PCM streaming, and compatibility with the Gemini 2.5 Live native audio endpoint.

### 1. Backend: /voice-proxy (Node.js)

This service is designed for Google Cloud Run. It uses `google-auth-library` to fetch tokens and handles the bidirectional binary stream.

**server.js**
```javascript
const WebSocket = require('ws');
const { GoogleAuth } = require('google-auth-library');

const PORT = process.env.PORT || 8080;
const LOCATION = process.env.LOCATION || 'us-central1';
const MODEL = 'gemini-2.5-flash-native-audio-preview-12-2025';

// Upstream Gemini endpoint
const UPSTREAM_URL = `wss://${LOCATION}-aiplatform.googleapis.com/ws/google.cloud.aiplatform.v1.LlmBidiService/BidiGenerateContent`;

const auth = new GoogleAuth({
  scopes: ['https://www.googleapis.com/auth/cloud-platform']
});

const wss = new WebSocket.Server({ port: PORT });

wss.on('connection', async (clientWs) => {
  console.log('Client connected to proxy');
  let upstreamWs = null;

  try {
    const accessToken = await auth.getAccessToken();
    upstreamWs = new WebSocket(UPSTREAM_URL, {
      headers: { Authorization: `Bearer ${accessToken}` }
    });

    upstreamWs.on('open', () => {
      // 1. Send Setup Frame immediately
      const setup = {
        setup: {
          model: `projects/${process.env.PROJECT_ID}/locations/${LOCATION}/publishers/google/models/${MODEL}`,
          generation_config: { response_modalities: ["AUDIO"] },
          system_instruction: {
            parts: [{ text: "You are Josh, a professional AI receptionist. Speak naturally. Concise responses (<30 words). Spoken audio only." }]
          },
          speech_config: {
            voice_config: { prebuilt_voice_config: { voice_name: "Kore" } }
          }
        }
      };
      upstreamWs.send(JSON.stringify(setup));
    });

    upstreamWs.on('message', (data) => clientWs.send(data));
    clientWs.on('message', (data) => {
      if (upstreamWs?.readyState === WebSocket.OPEN) upstreamWs.send(data);
    });

    // Keep-alive heartbeat
    const heartbeat = setInterval(() => {
      if (upstreamWs?.readyState === WebSocket.OPEN) upstreamWs.ping();
    }, 5000);

    const cleanup = () => {
      clearInterval(heartbeat);
      upstreamWs?.close();
      clientWs.close();
    };

    upstreamWs.on('close', cleanup);
    clientWs.on('close', cleanup);
    upstreamWs.on('error', cleanup);
    clientWs.on('error', cleanup);

  } catch (err) {
    console.error('Failed to init proxy:', err);
    clientWs.close();
  }
});

console.log(`Voice Proxy listening on ${PORT}`);
```

**Dockerfile**
```dockerfile
FROM node:20-slim
WORKDIR /app
COPY package*.json ./
RUN npm install --production
COPY . .
EXPOSE 8080
CMD ["node", "server.js"]
```

**Deployment Commands**
```bash
# 1. Build and push to Artifact Registry
gcloud builds submit --tag gcr.io/YOUR_PROJECT_ID/voice-proxy

# 2. Deploy to Cloud Run
gcloud run deploy voice-proxy \
  --image gcr.io/YOUR_PROJECT_ID/voice-proxy \
  --platform managed \
  --region us-central1 \
  --allow-unauthenticated \
  --set-env-vars PROJECT_ID=YOUR_PROJECT_ID,LOCATION=us-central1
```

### 2. Frontend: components/VoiceAgentDemo.tsx

I have updated the component with the requested `STREAMING_VOICE_ENABLED` flag and prepared the PCM streaming logic.

