    upstreamWs = new WebSocket(UPSTREAM_URL, {
      headers: { Authorization: `Bearer ${accessToken}` }
    });

    upstreamWs.on('open', () => {
      // 1. MANDATORY SETUP FRAME WITH EXACT VAD CONFIG
      const setupFrame = {
        setup: {
          model: `projects/${PROJECT_ID}/locations/${LOCATION}/publishers/google/models/${MODEL}`,
          generation_config: {
            response_modalities: ["AUDIO"],
            speech_config: {
              voice_config: {
                prebuilt_voice_config: {
                  voice_name: "Kore"
                }
              }
            },
            vad_config: {
              start_sensitivity: "LOW",
              end_sensitivity: "HIGH"
            }
          },
          system_instruction: {
            parts: [
              {
                text: "You are Josh, an Elite Agent Hub voice demo. Speak naturally and professionally. Keep responses under 40 words. Spoken audio only. No markdown. No lists. No medical, legal, or emergency advice."
              }
            ]
          }
        }
      };
      upstreamWs.send(JSON.stringify(setupFrame));
      console.log('Gemini Live Setup Frame sent');

      // 2. JSON HEARTBEAT (Every 5 seconds)
      // Sending empty media_chunks acts as a keep-alive frame for the Bidi service
      heartbeat = setInterval(() => {
        if (upstreamWs.readyState === WebSocket.OPEN) {
          const heartbeatFrame = { realtime_input: { media_chunks: [] } };
          upstreamWs.send(JSON.stringify(heartbeatFrame));
        }
      }, 5000);
    });

    // Transparent pipe: Upstream -> Client
    upstreamWs.on('message', (data) => {
      if (clientWs.readyState === WebSocket.OPEN) {
        clientWs.send(data);
      }
    });

    // Transparent pipe: Client -> Upstream
    clientWs.on('message', (data) => {
      if (upstreamWs && upstreamWs.readyState === WebSocket.OPEN) {
        upstreamWs.send(data);
      }
    });

    // Error & Close Handling
    upstreamWs.on('close', cleanup);
    clientWs.on('close', cleanup);
    upstreamWs.on('error', (e) => { 
      console.error('Upstream Error:', e.message); 
      cleanup(); 
    });
    clientWs.on('error', (e) => { 
      console.error('Client Error:', e.message); 
      cleanup(); 
    });

  } catch (err) {
    console.error('Handshake failed:', err);
    clientWs.close(1011, 'Internal Error');
  }
});

